// Purpose: to avoid losing form inputs on refresh. This slice will save form data to redux store when onBlur is triggered in a form field.
// This slice will handle the form data for a recipient_envelope component, allowing it to be saved and cleared as needed.  
// Note: Sending form data to API happens in apiSlice, not here.
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { PURGE } from "redux-persist";
//PayloadAction is a TypeScript type that describes the structure of Redux actions that carry data.

//can be used to replace type in PayloadAction: objects that might have a property set, mark those properties as optional by adding a question mark (?) to the end of their names.
interface CampaignLevel {
  id: number;
  level: {
    level: string;
    reference_id: string;
    unit_price: string;
    max_quantity: number;
    starting_deposit: string;
    description: string;
  };
  is_active: boolean;
  start_date: string;
  end_date: string;
  notes: string;
  created_by: string;
  created: string;
}

interface coData {
  id?: string;
  name?: string;
  street_address?: string;
  locality?: string;
  state?: string;
  post_code?: string;
  phoneNumber?: string;
  current_campaign_level?: CampaignLevel[];
}

const initialState: { coData: coData } = {
  coData:{}
};

const coSlice = createSlice({
name: 'co',
initialState,
reducers:{ 
      // updateCo: (state, action: PayloadAction<Record<string, unknown>>) => {  //*The action's payload is an object with string keys and values of any type
      updateCo: (state, action: PayloadAction<coData>) => {  //*The action's payload is an object with string keys and values of any type
        state.coData = { ...state.coData, ...action.payload };
      // copies all existing properties from state.formData and then overwrites or adds properties from action.payload.
      // This means any fields in action.payload will update the corresponding fields, while other fields remain unchanged.
    },

    clearCo: (state) => {
      state.coData = {};
    },
  },

  extraReducers: (builder) => {
    builder.addCase(PURGE, (state) => {
      // When PURGE action is dispatched, remove all form data
      state.coData = {};
    });
  }  
});

// Export actions
export const { updateCo, clearCo } = coSlice.actions;

// Export reducer to store.js
export default coSlice.reducer; 

//to update co in component: const dispatch = useDispatch() 

